    del_flag = '0'
    and host_id = #{hostId}
    and container_name like concat('%', #{containerName}, '%')
    and container_status = #{containerStatus}
    and schedule_status = #{scheduleStatus}
    and index_num = #{indexNum}
    and assigned_user_id = #{assignedUserId}
    and bound_account_no like concat('%', #{boundAccountNo}, '%')

order by host_id asc, index_num asc, container_id asc

select min(container_id) as container_id, host_id, index_num, concat('实例位 ', index_num) as container_name, case when count(distinct assigned_user_id) = 1 then max(assigned_user_id) else null end as assigned_user_id, case when count(distinct assigned_user_id) = 1 then max(assigned_user_name) else null end as assigned_user_name, count(1) as container_count, sum(case when lower(container_status) = 'running' then 1 else 0 end) as running_count, count(distinct assigned_user_id) as assigned_count, case when count(distinct android_type) = 1 then max(android_type) else 'MIXED' end as android_type, case when sum(case when lower(container_status) = 'running' then 1 else 0 end) = count(1) then 'running' when sum(case when lower(container_status) = 'running' then 1 else 0 end) = 0 then min(container_status) else 'partial' end as container_status, case when count(distinct schedule_status) = 1 then max(schedule_status) else 'MIXED' end as schedule_status, min(create_time) as create_time, max(update_time) as update_time, '0' as del_flag from cloud_container
del_flag = '0' and host_id = #{hostId} and container_status = #{containerStatus} and schedule_status = #{scheduleStatus} and index_num = #{indexNum} and assigned_user_id = #{assignedUserId}
group by host_id, index_num order by host_id asc, index_num asc

mapper.update:
update cloud_container
container_name = #{containerName}, instance_id = #{instanceId}, index_num = #{indexNum}, container_status = #{containerStatus}, schedule_status = #{scheduleStatus}, android_type = #{androidType}, container_ip = #{containerIp}, network_name = #{networkName}, image = #{image}, width = #{width}, height = #{height}, dpi = #{dpi}, webrtc_tcp_port = #{webrtcTcpPort}, webrtc_udp_port = #{webrtcUdpPort}, adb_port = #{adbPort}, bound_account_id = #{boundAccountId}, bound_account_no = #{boundAccountNo}, assigned_user_id = #{assignedUserId}, assigned_user_name = #{assignedUserName}, raw_json = #{rawJson}, update_by = #{updateBy}, update_time = sysdate()
where container_id = #{containerId}

update cloud_container
set schedule_status = 'IDLE', current_task_id = null, lock_owner = null, lock_expire_time = null, update_time = sysdate()
where container_id = #{containerId}
